  const limits = { ...DEFAULT_CAPTURE_LIMITS, ...overrides };
  for (const [name, value] of Object.entries(limits)) {
    if (!Number.isSafeInteger(value) || value <= 0) throw new Error(`Capture limit ${name} must be a positive integer.`);
  }
  return limits;
}

