    await runProcess("git", ["add", "value.ts"], submodule);
    await runProcess("git", ["commit", "-m", "submodule initial"], submodule);
    await runProcess("git", ["add", "deps/lib"], repository);
    await runProcess("git", ["commit", "-m", "add gitlink"], repository);
